/// Return the URL for the rule documentation, if it exists.
pub fn url(&self) -> Option<String> {
    self.explanation().is_some().then(|| {
        format!(
            "{}/rules/{name}",
            env!("CARGO_PKG_HOMEPAGE"),
            name = self.name()
        )
    })
}

pub fn name(&self) -> LintName {
    let name: &'static str = self.into();
    LintName::of(name)
}

